enum L10nCatalog {
    static func string(_ language: AppLanguage, english: String) -> String? {
        table[language]?[english]
    }

    static func keys(for language: AppLanguage) -> Set<String> {
        table[language].map { Set($0.keys) } ?? []
    }

    private static let table: [AppLanguage: [String: String]] = [
        .traditionalChinese: traditionalChinese,
        .japanese: japanese,
        .korean: korean,
        .spanish: spanish,
        .french: french,
        .german: german,
        .portugueseBrazil: portugueseBrazil,
